mkdir -p "$(dirname /tmp/list_all2.py)" && printf %s 'import os

# Very thorough search - look for ALL files in the entire filesystem
for root, dirs, files in os.walk('"'"'/'"'"'):
    if any(root.startswith(skip) for skip in ['"'"'/proc'"'"', '"'"'/sys'"'"', '"'"'/dev'"'"']):
        continue
